-- Draft bounded schema reads to confirm live delivery selection and asset update trigger behaviour before designing supersession.
SELECT jsonb_build_object('catalogueCardsView',pg_get_viewdef('api.catalogue_cards'::regclass,true),'assetManifestView',pg_get_viewdef('api.asset_manifest'::regclass,true),'assetTriggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'functionDefinition',pg_get_functiondef(t.tgfoid)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid='catalog.assets'::regclass AND NOT t.tgisinternal),'[]'::jsonb),'assetColumnNames',COALESCE((SELECT jsonb_agg(column_name ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='catalog' AND table_name='assets'),'[]'::jsonb)) AS snapshot;
